import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

print('Package comparison (baseline -> after):')
for proj in baseline.get('projects', []):
    name = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            pid = pkg['id']
            rv = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
            # find in after
            for ap in after.get('projects', []):
                if ap['path'] == proj['path']:
                    for afw in ap.get('frameworks', []):
                        for apkg in afw.get('topLevelPackages', []):
                            if apkg['id'] == pid:
                                arv = apkg.get('resolvedVersion', apkg.get('requestedVersion','?'))
                                if rv != arv:
                                    print(f'  {name}: {pid} {rv} -> {arv}')
print('Done')
"

